style.css:
@-moz-document domain("arizona-rp.com"), domain("forum.arizona-rp.com") {
/* Основной фон страницы */
body {
    background-image: url("https://img1.akspic.ru/previews/6/1/1/0/7/170116/170116-anime-sukuna_dzyu_dzyucu_kajsen-satoru_godzyo-nobara_kugisaki-dzhiu_dzhitsu_kajsen-500x.jpg") !important;
    background-attachment: fixed !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
}

/* Затемнение контента для лучшей читаемости */
.p-nav, 
.block-container, 
.p-footer, 
.buttonGroup, 
.pageNav-main, 
.pageNav-jump, 
.tabPanes, 
.menu-content, 
.overlay,
.block-minorHeader,
.thread-list,
.message,
.bbWrapper,
.node-body,
.structItem-container,
.message-cell,
.message-userDetails,
.block-body,
.block-row,
.tabs,
.fr-wrapper {
    background-color: rgba(18, 20, 30, 0.85) !important;
    border-radius: 8px !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
}

/* Улучшение читаемости текста */
.message-body,
.bbWrapper,
.node-description,
.message-signature,
.block-row,
.thread-list .structItem-cell,
.structItem-title,
.structItem-pageJump,
.structItem-status,
.message-userTitle,
.message-newIndicator,
.bbCodeBlock-content,
.bbCodeQuote-content,
.bbCodeTable {
    color: #ffffff !important;
    text-shadow: 0 1px 2px rgba(0,  0, 0, 0.7) !important;
}

/* Заголовки */
.block-header,
.block-minorHeader,
.message-cell .message-userDetails,
.structItem-title,
.p-title-value,
.p-sectionHeader,
.menu-header,
.bbCodeBlock-title,
.bbCodeQuote-title,
.block-tabHeader .tabs-tab {
    color: #ffffff !important;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8) !important;
    font-weight: bold !important;
}

/* Ссылки */
a,
.block-link,
.menu-linkRowLink,
.structItem-pageJump a,
.p-breadcrumbs a,
.pageNav-jump a {
    color: #00A8FF !important;
    text-decoration: none !important;
}

a:hover,
.block-link:hover,
.menu-linkRowLink:hover,
.structItem-pageJump a:hover,
.p-breadcrumbs a:hover,
.pageNav-jump a:hover {
    color: #00d9ff !important;
    text-shadow: 0 0 5px rgba(0, 217, 255, 0.5) !important;
}

/* Кнопки */
.button,
.button--primary,
.button--cta,
.button--link,
.button--scroll {
    background: linear-gradient(135deg, #00A8FF, #0077cc) !important;
    border: none !important;
    color: white !important;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.3) !important;
    border-radius: 5px !important;
    transition: all 0.3s ease !important;
}

.button:hover,
.button--primary:hover,
.button--cta:hover,
.button--link:hover,
.button--scroll:hover {
    background: linear-gradient(135deg, #00d9ff, #0099ff) !important;
    transform: translateY(-2px) !important;
    box-shadow: 0 4px 12px rgba(0, 168, 255, 0.4) !important;
}

/* Навигация */
.p-nav-list .p-navEl.is-selected,
.menu-tabHeader .tabs-tab.is-active,
.block-tabHeader .tabs-tab.is-active {
    background: rgba(0, 168, 255, 0.2) !important;
    color: #00d9ff !important;
    border-color: #00A8FF !important;
}

.p-navEl-link,
.menu-linkRowLink {
    color: #cccccc !important;
}

.p-navEl-link:hover,
.menu-linkRowLink:hover {
    color: #00d9ff !important;
}

/* Формы */
.input,
.textInput,
.textarea,
.select,
.fr-box {
    background: rgba(255, 255, 255, 0.1) !important;
    border: 1px solid rgba(0, 168, 255, 0.3) !important;
    color: white !important;
    border-radius: 5px !important;
}

.input:focus,
.textInput:focus,
.textarea:focus,
.select:focus,
.fr-box:focus {
    border-color: #00A8FF !important;
    box-shadow: 0 0 10px rgba(0, 168, 255, 0.3) !important;
    outline: none !important;
}

/* Блоки кода */
.bbCodeBlock {
    background: rgba(0, 0, 0, 0.6) !important;
    border-left: 3px solid #00A8FF !important;
    border-radius: 5px !important;
}

.bbCodeBlock-title {
    background: rgba(0, 168, 255, 0.2) !important;
    color: #00d9ff !important;
    font-weight: bold !important;
    padding: 10px !important;
}

/* Уведомления */
.messageNotice,
.alert {
    background: rgba(0, 168, 255, 0.15) !important;
    border-left: 3px solid #00A8FF !important;
    color: #ffffff !important;
}

/* Аватарки */
.avatar,
.message-avatar {
    border: 2px solid rgba(0, 168, 255, 0.5) !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3) !important;
    border-radius: 50% !important;
}

/* Ховер-эффекты */
.structItem:hover,
.message:hover,
.block-row:hover,
.menu-linkRow:hover {
    background: rgba(0, 168, 255, 0.1) !important;
    transform: translateX(5px) !important;
    transition: all 0.3s ease !important;
}

/* Скроллбар */
::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
}

::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2) !important;
    border-radius: 5px !important;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(135deg, #00A8FF, #0077cc) !important;
    border-radius: 5px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(135deg, #00d9ff, #0099ff) !important;
}

/* Иконки и баджи */
.badge,
.badge--highlighted,
.message-newIndicator {
    background: #00A8FF !important;
    color: white !important;
    text-shadow: none !important;
    border: none !important;
}

/* Пагинация */
.pageNav-page,
.pageNav-jump {
    background: rgba(18, 20, 30, 0.8) !important;
}

.pageNav-page.pageNav-page--current {
    background: #00A8FF !important;
    color: white !important;
}

/* Футер */
.p-footer {
    background: rgba(0, 0, 0, 0.7) !important;
    border-top: 2px solid #00A8FF !important;
}

/* Адаптивность для мобильных */
@media (max-width: 768px) {
    .p-nav,
    .block-container,
    .message {
        background-color: rgba(18, 20, 30, 0.9) !important;
    }
    
    .structItem:hover,
    .message:hover {
        transform: translateX(0) !important;
    }
}

/* Анимации */
.button,
.p-navEl,
.menu-linkRow,
.structItem {
    transition: all 0.3s ease !important;
}

/* Тени для контраста */
.block-header,
.p-title,
.menu-header {
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8) !important;
}
}
